#!/usr/bin/env bash
# ============================================================================
# VideoMind rebuild, Part 4b: Claude on a current model, with structured outputs
# ============================================================================
# FOR THE rebuild BRANCH ONLY. It refuses to run on main.
#
# Until now every Claude call named claude-opus-4-5 in code, asked for
# "ONLY valid JSON" and took the answer apart by hand. An answer that did
# not parse was saved as "Analysis pending." and the video counted as done.
#
# After this part:
#   * one setting picks the model: CLAUDE_MODEL, default claude-sonnet-5-5.
#     Picking which videos a library question is about uses a small fast
#     one: CLAUDE_MODEL_FAST, default claude-haiku-5-5. CLAUDE_EFFORT
#     (low to max) is optional
#   * every answer is a structured output: the request carries a JSON
#     schema and the answer is held to it. No more hand parsing
#   * the transcript is given to Claude as lines that start with their
#     second, so chapter, highlight and source times are real seconds
#   * the analysis is checked before it is saved: chapters in order and
#     inside the video, highlights cut at the end, tags without # and
#     repeats (at most 10). An analysis without a summary is never saved
#   * a refusal stops the analysis at once with a clear reason (the owner
#     can retry). An answer cut off is asked for once more with twice the
#     room. An unreadable answer is tried again by the queue
#   * Ask a video sends the transcript as a cached block, so the second
#     and later questions about one video cost less
#   * Ask and the library answer 422 when Claude declines and 503 when
#     the AI service is busy, with a plain message, instead of a 500
#     carrying the provider's own text
#   * every reply, including a retried one, is in the usage ledger
#
#   BACKEND   1 new file, 7 changed. @anthropic-ai/sdk goes from 0.30 to
#             0.128 (package.json and package-lock.json); the script runs
#             npm install in backend. No database change.
#   FRONTEND  nothing.
#
#   ./vm_claude.sh            apply (needs Part 4a on the branch)
#   ./vm_claude.sh --force    apply even if local files differ from GitHub
#   ./vm_claude.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_claude"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_claude_backups"

ADD=(
  "backend/src/services/claude.ts"
)
MOD=(
  "backend/.env.example"
  "backend/package.json"
  "backend/package-lock.json"
  "backend/src/routes/chat.ts"
  "backend/src/routes/learn.ts"
  "backend/src/services/aiPipeline.ts"
  "backend/src/services/learningService.ts"
  "backend/src/services/pipeline.ts"
)
PRE_MOD=(
