B64_A0
verify "$TMPD/a0" "${NEW_ADD[0]}" "backend/src/services/claude.ts"

grep -q "$MARKER" "$TMPD/a0"                                   || die "claude.ts payload missing marker. Aborting."
grep -q 'output_config' "$TMPD/a0"                               || die "claude.ts payload does not ask for structured outputs. Aborting."
grep -q 'claude-sonnet-5-5' "$TMPD/a0"                           || die "claude.ts payload missing the default model. Aborting."
grep -q '"@anthropic-ai/sdk": "\^0.128.0"' "$TMPD/m1"      || die "package.json payload has the wrong SDK version. Aborting."
grep -q '"version": "0.128.0"' "$TMPD/m2"           || die "package-lock.json payload has the wrong SDK version. Aborting."
grep -q 'transcribePiece' "$TMPD/m5"          || die "aiPipeline.ts payload lost transcription. Aborting."
grep -q 'cache_control' "$TMPD/m5"            || die "aiPipeline.ts payload missing the cached transcript. Aborting."
if grep -q 'claude-opus-4-5' "$TMPD/m5" "$TMPD/m6"; then die "payload still names claude-opus-4-5. Aborting."; fi
grep -q 'transcribeLong' "$TMPD/m7"              || die "pipeline.ts payload lost the long transcription. Aborting."
grep -q 'ClaudeError' "$TMPD/m7"                 || die "pipeline.ts payload missing the refusal handling. Aborting."
grep -q 'claudeFailure' "$TMPD/m3"                     || die "chat.ts payload missing error mapping. Aborting."
grep -q 'canView' "$TMPD/m3"                           || die "chat.ts payload lost the private check. Aborting."
say "9 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied Claude on a current model with structured outputs (rebuild Part 4b)."

# ---- packages: the source is in place either way, so a failed install
# ---- is reported, not rolled back.
say "backend: installing @anthropic-ai/sdk 0.128.0 (npm install) ..."
if (cd backend && npm install --no-audit --no-fund >/dev/null 2>&1); then
  say "backend packages installed."
else
  say "WARNING: npm install failed (no network?). The files are applied."
  say "         Run this yourself before the checks below: cd backend && npm install"
fi

say "Verify before pushing:"
say "  cd backend && npx tsc --noEmit && npm run build"
say "Undo: ./vm_claude.sh --revert"
